def deck(n):
 k=CH[n]
 if k not in DECKS: DECKS[k]={'title':TITLES[n] if n!=15 else '综合项目工作坊与项目评价','slides':[]}
 return DECKS[k]['slides']
def ref(n,custom=None):
 sec,anchor=custom or REF[n]
 return {'chapter':CH[n],'section':sec,'anchor':anchor}
def flow(labels):
 return {'kind':'flow','items':[{'title':a,'text':b} for a,b in labels]}
def cards(labels):
 return {'kind':'cards','items':[{'title':a,'text':b} for a,b in labels]}
def table(headers,rows): return {'kind':'table','headers':headers,'rows':rows}
def s(n,section,title,lead,p1,p2,takeaway,visual=None,equation=None,custom=None,**extra):
 x={'kind':'concept','lessonNumber':n,'section':f'第{n}讲 · {section}' if n in (15,16) else section,'title':title,'lead':lead,'body':[p1,p2],'takeaway':takeaway,'layout':'split' if visual else 'stack','detailRef':ref(n,custom), 'sourceSection':section, 'density':'compact'}
 if visual: x['visual']=visual
 if equation: x['equation']=equation
 x.update(extra);deck(n).append(x);return x

def case(n,i,company,title,context,decision,facts,analysis,limits,q,a,url,sourceTitle,publisher,date,labels,custom=None):
 c={'id':f'b{n}-{i:02}','lesson':n,'chapter':CH[n],'company':company,'title':title,'context':context,'decision':decision,'facts':facts,'analysis':analysis,'limits':limits,'questions':[{'question':q,'answer':a}],'sources':[{'title':sourceTitle,'url':url,'publisher':publisher,'date':date,'accessed':'2026-10-17','support':'；'.join(facts)}]}
 CASES.append(c)
 x=s(n,'商业案例',title,decision,context+facts[0],facts[1]+analysis.removeprefix('课程分析：'),limits,flow(labels),custom=custom,kind='case',caseId=c['id'],sources=[{'title':sourceTitle,'url':url}],caseNumber=i)
 x['sourceCaveat']=limits
 return c

