def place_cases(chapter,positions):
 xs=DECKS[chapter]['slides']; core=[x for x in xs if not x.get('caseId')]; cases=[x for x in xs if x.get('caseId')]
 result=[]
 for i,x in enumerate(core):
  result.append(x)
  if i in positions:
   wanted=positions[i]
   result.extend(y for y in cases if y['caseId']==wanted)
 # Positions completely cover all cases.
 missing=[x for x in cases if x not in result]
 if missing: raise ValueError((chapter,'unplaced cases',[x['caseId'] for x in missing]))
 DECKS[chapter]['slides']=result

def register_term(n,term,aliases,definition,explanation):
 xs=[x for x in deck(n) if x.get('lessonNumber')==n]
 hits=[x for x in xs if any(a in (' '.join([x.get('title',''),x.get('lead',''),' '.join(x.get('body',[])),json.dumps(x.get('visual',{}),ensure_ascii=False),json.dumps(x.get('diagram',{}),ensure_ascii=False)])) for a in [term]+aliases)]
 if not hits: raise ValueError(('missing term',n,term))
 ds=next((x for x in xs if x['title']==definition),None)
 if not ds: raise ValueError(('missing definition',n,term,definition))
 first=hits[0]
 TERMS.append({'chapter':CH[n],'lesson':n,'term':term,'aliases':aliases,'firstSlideTitle':first['title'],'definitionSlideTitle':definition,'explanation':explanation,'definitionAtOrBeforeFirstUse':xs.index(ds)<=xs.index(first)})

